import{_ as e,c as a,o as t,ah as s}from"./chunks/framework.Dnh4IO1K.js";const h=JSON.parse('{"title":"34、【大壮】 乾下震上","description":"周易口诀义 - 34、【大壮】 乾下震上","frontmatter":{"title":"34、【大壮】 乾下震上","description":"周易口诀义 - 34、【大壮】 乾下震上"},"headers":[],"relativePath":"zh/classics/koujueyi/036.md","filePath":"zh/classics/koujueyi/036.md"}'),r={name:"zh/classics/koujueyi/036.md"};function i(o,p,_,c,n,l){return t(),a("div",null,[...p[0]||(p[0]=[s('<h1 id="_34、【大壮】-乾下震上" tabindex="-1">34、【大壮】 乾下震上 <a class="header-anchor" href="#_34、【大壮】-乾下震上" aria-label="Permalink to “34、【大壮】 乾下震上”">​</a></h1><p>彖曰：大壮，大者壮也。刚以动，故壮。「大壮利贞」，大者正也。正大而天地之情可见矣。</p><p>象曰：雷在天上，大壮。君子以非礼弗履。</p><p>初九：壮于趾，征凶，有孚。</p><p>象曰：「壮于趾」，其孚穷也。</p><p>九二：贞吉。</p><p>象曰：「九二贞吉」，以中也。</p><p>九三：小人用壮，君子用罔，贞厉。羝羊触藩，羸其角。</p><p>象曰：「小人用壮」，君子罔也。</p><p>九四：贞吉，悔亡。藩决不羸，壮于大，与之輹。</p><p>象曰：「藩决不羸」，尚往也。</p><p>六五：丧羊于易，无悔。</p><p>象曰：「丧羊于易」，位不当也。</p><p>上六：羝羊触藩，不能退，不能遂，无攸利，艰则吉。</p><p>象曰：「不能退，不能遂」，不详也。「艰则吉」，咎不长也。</p><p>无（四库全书标明，摘录时缺豫、随、无妄、大壮、晋、睽、蹇、解、中孚八卦）</p>',16)])])}const u=e(r,[["render",i]]);export{h as __pageData,u as default};
